module.exports = [
{ e: "🥚", art: { b: "🥚", s: ["🪺", "🐣", "🦕", "🌿"], c: ["#5A4A1B", "#C2A04A"] },
pt: { h: "Na feira, Leo segurou um ovo de avestruz enorme e perguntou se os ovos de dinossauro eram ainda maiores. “Alguns eram!”, disse o vovô. “E os cientistas descobriram que muitos dinossauros cuidavam dos filhotes em ninhos, como as aves.” Nina achou isso muito fofo.", t: "Ovos e filhotes", f: "Todos os dinossauros botavam ovos. Muitos faziam ninhos no chão, às vezes em grandes colônias, com dezenas de ninhos perto uns dos outros. Alguns chocavam os ovos sentados em cima deles, como as galinhas fazem hoje.", x: "Um dinossauro chamado Maiassaura ganhou um nome que quer dizer “lagarto boa mãe”, porque foram encontrados ninhos dele com filhotes que pareciam receber comida e cuidado dos pais!", s: ["Os maiores ovos de dinossauro encontrados tinham mais de 40 centímetros de comprimento.", "Mesmo os gigantes saíam de ovos relativamente pequenos e cresciam muito rápido.", "Alguns ovos fossilizados ainda guardam embriões de dinossauro lá dentro!"], ex: { t: "A força da casca", m: "4 cascas de ovo cortadas ao meio pelo adulto (só a parte redonda de cima), fita adesiva, livros", p: ["Com um adulto, prepare 4 metades de casca com a borda lisa, coladas com fita por fora para não rachar.", "Coloque as 4 cascas com a parte redonda para cima, formando um quadrado.", "Empilhe livros em cima, um de cada vez. Quantos elas aguentam? O formato de cúpula deixa a casca muito forte!"] }, at: "Ficha do ninho", m: "papel, lápis de cor, algodão ou palha (opcional)", p: ["Desenhe um ninho de dinossauro com ovos e um filhote saindo da casca.", "Desenhe a mãe ou o pai cuidando do ninho.", "Cole um pouco de algodão ou palha no ninho e coloque a ficha no museu."], q: "Como você imagina que era o primeiro dia de vida de um filhote de dinossauro?" },
en: { h: "At the market, Leo held a huge ostrich egg and asked whether dinosaur eggs were even bigger. “Some were!” said Grandpa. “And scientists discovered that many dinosaurs cared for their babies in nests, like birds.” Nina thought that was adorable.", t: "Eggs and babies", f: "All dinosaurs laid eggs. Many built nests on the ground, sometimes in big colonies with dozens of nests close together. Some sat on their eggs to keep them warm, as chickens do today.", x: "A dinosaur called Maiasaura got a name meaning “good mother lizard,” because its nests were found with babies that seemed to be fed and cared for by their parents!", s: ["The largest dinosaur eggs found were more than 40 centimeters (16 inches) long.", "Even the giants hatched from fairly small eggs and grew very fast.", "Some fossilized eggs still hold dinosaur embryos inside!"], ex: { t: "The strength of eggshells", m: "4 eggshells cut in half by a grown-up (just the rounded top part), tape, books", p: ["With a grown-up, prepare 4 half-shells with smooth edges, taped on the outside so they don't crack.", "Place the 4 shells dome side up in a square.", "Stack books on top, one at a time. How many can they hold? The dome shape makes the shell very strong!"] }, at: "Nest card", m: "paper, colored pencils, cotton or straw (optional)", p: ["Draw a dinosaur nest with eggs and a baby hatching.", "Draw the mother or father looking after the nest.", "Glue a little cotton or straw on the nest and put the card in the museum."], q: "What do you imagine a baby dinosaur's first day was like?" },
es: { h: "En la feria, Leo sostuvo un huevo de avestruz enorme y preguntó si los huevos de dinosaurio eran todavía más grandes. “¡Algunos sí!”, dijo el abuelo. “Y los científicos descubrieron que muchos dinosaurios cuidaban a sus crías en nidos, como las aves.” A Nina le pareció muy tierno.", t: "Huevos y crías", f: "Todos los dinosaurios ponían huevos. Muchos hacían nidos en el suelo, a veces en grandes colonias, con decenas de nidos cerca unos de otros. Algunos se sentaban sobre los huevos para darles calor, como hacen hoy las gallinas.", x: "¡Un dinosaurio llamado Maiasaura recibió un nombre que quiere decir “lagarto buena madre”, porque se encontraron nidos suyos con crías que parecían recibir comida y cuidado de sus padres!", s: ["Los huevos de dinosaurio más grandes que se encontraron medían más de 40 centímetros de largo.", "Incluso los gigantes salían de huevos relativamente pequeños y crecían muy rápido.", "¡Algunos huevos fosilizados todavía guardan embriones de dinosaurio adentro!"], ex: { t: "La fuerza de la cáscara", m: "4 cáscaras de huevo cortadas por la mitad por un adulto (solo la parte redonda de arriba), cinta adhesiva, libros", p: ["Con un adulto, prepara 4 mitades de cáscara con el borde parejo, con cinta por fuera para que no se rajen.", "Pon las 4 cáscaras con la parte redonda hacia arriba, formando un cuadrado.", "Apila libros encima, de a uno. ¿Cuántos aguantan? ¡La forma de cúpula hace que la cáscara sea muy fuerte!"] }, at: "Ficha del nido", m: "papel, lápices de colores, algodón o paja (opcional)", p: ["Dibuja un nido de dinosaurio con huevos y una cría saliendo del cascarón.", "Dibuja a la mamá o al papá cuidando el nido.", "Pega un poco de algodón o paja en el nido y pon la ficha en el museo."], q: "¿Cómo imaginas que era el primer día de vida de una cría de dinosaurio?" } },

{ e: "🌿", art: { b: "🌿", s: ["🍖", "🦷", "🪨", "💩"], c: ["#2A4E1B", "#5AA03A"] },
pt: { h: "No almoço, Leo reparou que o vovô mastigava devagar e perguntou se os dinossauros também mastigavam. “Alguns sim, outros não!”, respondeu o vovô. “E alguns engoliam pedras para ajudar a moer a comida dentro da barriga, como as galinhas fazem até hoje.”", t: "O que os dinossauros comiam?", f: "A maioria dos dinossauros era herbívora, ou seja, comia plantas. Outros eram carnívoros e caçavam ou comiam restos de animais. Alguns comiam de tudo um pouco. Os cientistas descobrem o cardápio pelos dentes, pelo formato da cabeça e até pelo cocô fossilizado.", x: "O cocô de dinossauro fossilizado tem até nome de cientista: coprólito! Dentro dele, os pesquisadores encontram pedacinhos de ossos e plantas que mostram o que o animal comeu.", s: ["Dentes pontudos e serrilhados, como facas, eram de carnívoros.", "Dentes achatados ou em forma de folha serviam para cortar e moer plantas.", "As pedras engolidas que ajudavam a moer a comida se chamam gastrólitos."], ex: { t: "Moela de saquinho", m: "um saquinho plástico com fecho, folhas de alface ou couve, algumas pedrinhas lisas e lavadas, um pouco de água", p: ["Coloque as folhas e um pouquinho de água no saquinho, sem as pedras, feche e aperte com a mão por um minuto.", "Agora coloque as pedrinhas junto, feche e aperte de novo pelo mesmo tempo.", "Com as pedras, as folhas ficam muito mais moídas! As galinhas, que são dinossauros, ainda usam esse truque na moela."] }, at: "Ficha do cardápio", m: "papel, lápis de cor", p: ["Desenhe três dentes: um de carnívoro, um de herbívoro e um de quem come de tudo.", "Ao lado de cada um, desenhe o prato favorito daquele dinossauro.", "Coloque a ficha no museu."], q: "Se você fosse um dinossauro, seria herbívoro, carnívoro ou comeria de tudo?" },
en: { h: "At lunch, Leo noticed Grandpa chewing slowly and asked whether dinosaurs chewed too. “Some did, some didn't!” Grandpa answered. “And some swallowed stones to help grind up food in their bellies, like chickens still do today.”", t: "What did dinosaurs eat?", f: "Most dinosaurs were herbivores, meaning they ate plants. Others were carnivores that hunted or ate leftovers. Some ate a bit of everything. Scientists figure out their menu from their teeth, the shape of their heads and even fossilized poop.", x: "Fossilized dinosaur poop even has a scientific name: coprolite! Inside, researchers find bits of bone and plants that show what the animal ate.", s: ["Pointy, serrated teeth, like knives, belonged to meat-eaters.", "Flat or leaf-shaped teeth were for cutting and grinding plants.", "Swallowed stones that helped grind food are called gastroliths."], ex: { t: "Gizzard in a bag", m: "a zip-top bag, lettuce or kale leaves, some smooth washed pebbles, a little water", p: ["Put the leaves and a little water in the bag without the stones, seal it and squeeze with your hand for a minute.", "Now add the pebbles, seal it and squeeze again for the same amount of time.", "With the stones, the leaves get much more mashed! Chickens, which are dinosaurs, still use this trick in their gizzards."] }, at: "Menu card", m: "paper, colored pencils", p: ["Draw three teeth: one from a meat-eater, one from a plant-eater and one from an eat-anything dinosaur.", "Next to each, draw that dinosaur's favorite meal.", "Put the card in the museum."], q: "If you were a dinosaur, would you be a plant-eater, a meat-eater or eat everything?" },
es: { h: "En el almuerzo, Leo notó que el abuelo masticaba despacio y preguntó si los dinosaurios también masticaban. “¡Algunos sí, otros no!”, respondió el abuelo. “Y algunos tragaban piedras para ayudar a moler la comida dentro de la panza, como hacen todavía hoy las gallinas.”", t: "¿Qué comían los dinosaurios?", f: "La mayoría de los dinosaurios eran herbívoros, es decir, comían plantas. Otros eran carnívoros y cazaban o comían restos de animales. Algunos comían un poco de todo. Los científicos descubren el menú por los dientes, la forma de la cabeza y hasta por la caca fosilizada.", x: "¡La caca de dinosaurio fosilizada hasta tiene nombre científico: coprolito! Adentro, los investigadores encuentran pedacitos de huesos y plantas que muestran qué comió el animal.", s: ["Los dientes puntiagudos y aserrados, como cuchillos, eran de carnívoros.", "Los dientes chatos o con forma de hoja servían para cortar y moler plantas.", "Las piedras tragadas que ayudaban a moler la comida se llaman gastrolitos."], ex: { t: "Molleja en una bolsita", m: "una bolsita con cierre, hojas de lechuga o repollo, algunas piedritas lisas y lavadas, un poco de agua", p: ["Pon las hojas y un poquito de agua en la bolsita, sin las piedras, ciérrala y apriétala con la mano durante un minuto.", "Ahora agrega las piedritas, ciérrala y apriétala otra vez el mismo tiempo.", "¡Con las piedras, las hojas quedan mucho más molidas! Las gallinas, que son dinosaurios, todavía usan ese truco en la molleja."] }, at: "Ficha del menú", m: "papel, lápices de colores", p: ["Dibuja tres dientes: uno de carnívoro, uno de herbívoro y uno de quien come de todo.", "Al lado de cada uno, dibuja el plato favorito de ese dinosaurio.", "Pon la ficha en el museo."], q: "Si fueras un dinosaurio, ¿serías herbívoro, carnívoro o comerías de todo?" } },

{ e: "🪽", art: { b: "🦅", s: ["☁️", "🌊", "🐟", "⛰️"], c: ["#1B3A5A", "#5A8AC2"] },
pt: { h: "Leo desenhou um “dinossauro voador” enorme, com asas de couro e um bico comprido. O vovô elogiou o desenho, mas fez uma correção: “Esse bicho é incrível, mas não era dinossauro! Era um pterossauro, um primo dos dinossauros. E alguns dos mais bonitos viveram no Ceará!”", t: "Os pterossauros, os répteis voadores", f: "Os pterossauros foram os primeiros animais com coluna vertebral a voar batendo asas. Suas asas eram feitas de pele, esticada entre o corpo e um dedo comprido da mão. Eles viveram na mesma época que os dinossauros, mas eram outro grupo de répteis.", x: "O Quetzalcoatlus, um dos maiores pterossauros, tinha asas de mais de 10 metros de ponta a ponta, do tamanho de um avião pequeno! E no Ceará foi encontrado o Tapejara, com uma crista enorme e colorida na cabeça.", s: ["Alguns pterossauros eram pequenos como um pardal, e outros eram gigantes.", "Muitos pescavam, voando baixinho sobre a água.", "A Chapada do Araripe, no Ceará, é um dos lugares do mundo com mais fósseis de pterossauros bem conservados."], ex: { t: "Asa de pele", m: "dois palitos de churrasco sem ponta, um saco plástico, fita adesiva, um ventilador ou o vento (com um adulto)", p: ["Prenda um pedaço de plástico entre os dois palitos, formando uma asa triangular, como a de um pterossauro.", "Segure pelos palitos na frente do ventilador ou ao vento, inclinando um pouquinho.", "Sinta a asa querer subir! Uma pele fina e esticada pode funcionar como asa, como nos pterossauros e nos morcegos."] }, at: "Ficha do Tapejara", m: "papel, lápis de cor", p: ["Desenhe um Tapejara voando sobre um lago, com uma crista enorme e bem colorida.", "Escreva “Não é dinossauro: é pterossauro!” e “Ceará, Brasil”.", "Pendure a ficha no teto do museu, como se estivesse voando."], q: "Se você pudesse voar como um pterossauro, para onde iria?" },
en: { h: "Leo drew a huge “flying dinosaur” with leathery wings and a long beak. Grandpa praised the drawing but made a correction: “That creature is amazing, but it wasn't a dinosaur! It was a pterosaur, a cousin of the dinosaurs. And some of the most beautiful ones lived in Brazil!”", t: "Pterosaurs, the flying reptiles", f: "Pterosaurs were the first animals with backbones to fly by flapping their wings. Their wings were made of skin stretched between the body and one very long finger. They lived at the same time as dinosaurs but were a different group of reptiles.", x: "Quetzalcoatlus, one of the biggest pterosaurs, had wings more than 10 meters (33 feet) from tip to tip, as wide as a small airplane! And in Brazil scientists found Tapejara, with a huge, colorful crest on its head.", s: ["Some pterosaurs were as small as a sparrow, and others were giants.", "Many caught fish, flying low over the water.", "The Araripe Plateau in Brazil is one of the places in the world with the most well-preserved pterosaur fossils."], ex: { t: "Skin wing", m: "two blunt bamboo skewers, a plastic bag, tape, a fan or the wind (with a grown-up)", p: ["Tape a piece of plastic between the two skewers to make a triangular wing, like a pterosaur's.", "Hold it by the skewers in front of the fan or in the wind, tilting it slightly.", "Feel the wing want to rise! A thin, stretched skin can work as a wing, as in pterosaurs and bats."] }, at: "Tapejara card", m: "paper, colored pencils", p: ["Draw a Tapejara flying over a lake, with a huge, colorful crest.", "Write “Not a dinosaur: a pterosaur!” and “Brazil.”", "Hang the card from the museum ceiling, as if it were flying."], q: "If you could fly like a pterosaur, where would you go?" },
es: { h: "Leo dibujó un “dinosaurio volador” enorme, con alas de cuero y un pico largo. El abuelo felicitó el dibujo, pero hizo una corrección: “Este bicho es increíble, ¡pero no era un dinosaurio! Era un pterosaurio, un primo de los dinosaurios. ¡Y algunos de los más lindos vivieron en Brasil!”", t: "Los pterosaurios, los reptiles voladores", f: "Los pterosaurios fueron los primeros animales con columna vertebral que volaron batiendo las alas. Sus alas eran de piel, estirada entre el cuerpo y un dedo larguísimo de la mano. Vivieron en la misma época que los dinosaurios, pero eran otro grupo de reptiles.", x: "¡El Quetzalcoatlus, uno de los pterosaurios más grandes, tenía alas de más de 10 metros de punta a punta, como un avión pequeño! Y en Brasil se encontró el Tapejara, con una cresta enorme y colorida en la cabeza.", s: ["Algunos pterosaurios eran pequeños como un gorrión, y otros eran gigantes.", "Muchos pescaban volando bajito sobre el agua.", "La Chapada do Araripe, en Brasil, es uno de los lugares del mundo con más fósiles de pterosaurios bien conservados."], ex: { t: "Ala de piel", m: "dos palitos de brochette sin punta, una bolsa de plástico, cinta adhesiva, un ventilador o el viento (con un adulto)", p: ["Pega un pedazo de plástico entre los dos palitos, formando un ala triangular, como la de un pterosaurio.", "Sostenla por los palitos frente al ventilador o al viento, inclinándola un poquito.", "¡Siente cómo el ala quiere subir! Una piel fina y estirada puede funcionar como ala, como en los pterosaurios y los murciélagos."] }, at: "Ficha del Tapejara", m: "papel, lápices de colores", p: ["Dibuja un Tapejara volando sobre un lago, con una cresta enorme y bien colorida.", "Escribe “¡No es dinosaurio: es pterosaurio!” y “Brasil”.", "Cuelga la ficha del techo del museo, como si estuviera volando."], q: "Si pudieras volar como un pterosaurio, ¿adónde irías?" } },

{ e: "🐊", art: { b: "🐋", s: ["🌊", "🐟", "🦑", "🐢"], c: ["#0B2A4E", "#2C6AA0"] },
pt: { h: "Na praia, Leo perguntou se tinha dinossauros nadando no mar. “Não exatamente”, respondeu o vovô. “Mas tinha répteis marinhos gigantes, alguns parecidos com golfinhos, outros com pescoço de cobra. Os dinossauros mesmo viviam em terra firme.”", t: "Os monstros do mar antigo", f: "Enquanto os dinossauros andavam em terra, os mares eram dominados por répteis marinhos. Os ictiossauros pareciam golfinhos, os plesiossauros tinham pescoço comprido e nadadeiras como remos, e os mossassauros eram enormes caçadores com dentes afiados.", x: "Os ictiossauros não botavam ovos: davam à luz filhotes vivos, dentro da água, como os golfinhos fazem hoje! Foram encontrados fósseis de mães com filhotes.", s: ["Os répteis marinhos respiravam ar e precisavam subir à superfície, como as baleias.", "Alguns mossassauros chegavam a mais de 15 metros de comprimento.", "As tartarugas marinhas são répteis antigos que nadavam nos mares daquela época e existem até hoje."], ex: { t: "Nadadeira x mão aberta", m: "uma bacia com água, uma colher de pau ou espátula larga, um garfo", p: ["Mexa a água empurrando com o garfo, como se fosse uma mão de dedos separados.", "Agora empurre com a colher larga, como uma nadadeira.", "Qual empurra mais água? Por isso os répteis marinhos tinham nadadeiras largas, e não dedos soltos!"] }, at: "Ficha do mar antigo", m: "papel, lápis de cor azul e verde", p: ["Desenhe um mar antigo com um ictiossauro, um plesiossauro e um mossassauro.", "Coloque peixes, amonites (conchas em espiral) e uma tartaruga.", "Escreva “Répteis marinhos: primos dos dinossauros” e coloque no museu."], q: "Qual desses monstros do mar você teria mais medo de encontrar?" },
en: { h: "At the beach, Leo asked whether there were dinosaurs swimming in the sea. “Not exactly,” Grandpa answered. “But there were giant sea reptiles, some like dolphins, others with snakelike necks. The actual dinosaurs lived on land.”", t: "Monsters of the ancient sea", f: "While dinosaurs walked on land, the seas were ruled by marine reptiles. Ichthyosaurs looked like dolphins, plesiosaurs had long necks and paddle-like flippers and mosasaurs were huge hunters with sharp teeth.", x: "Ichthyosaurs didn't lay eggs: they gave birth to live babies in the water, the way dolphins do today! Fossils of mothers with babies have been found.", s: ["Marine reptiles breathed air and had to come up to the surface, like whales.", "Some mosasaurs reached more than 15 meters (50 feet) long.", "Sea turtles are ancient reptiles that swam in the seas back then and still exist today."], ex: { t: "Flipper vs. open hand", m: "a basin of water, a wooden spoon or wide spatula, a fork", p: ["Stir the water by pushing with the fork, like a hand with spread fingers.", "Now push with the wide spoon, like a flipper.", "Which pushes more water? That's why marine reptiles had wide flippers instead of separate fingers!"] }, at: "Ancient sea card", m: "paper, blue and green colored pencils", p: ["Draw an ancient sea with an ichthyosaur, a plesiosaur and a mosasaur.", "Add fish, ammonites (spiral shells) and a turtle.", "Write “Marine reptiles: cousins of the dinosaurs” and put it in the museum."], q: "Which of these sea monsters would you be most scared to meet?" },
es: { h: "En la playa, Leo preguntó si había dinosaurios nadando en el mar. “No exactamente”, respondió el abuelo. “Pero había reptiles marinos gigantes, algunos parecidos a delfines y otros con cuello de serpiente. Los dinosaurios de verdad vivían en tierra firme.”", t: "Los monstruos del mar antiguo", f: "Mientras los dinosaurios caminaban por la tierra, los mares estaban dominados por reptiles marinos. Los ictiosaurios parecían delfines, los plesiosaurios tenían cuello largo y aletas como remos, y los mosasaurios eran enormes cazadores con dientes afilados.", x: "¡Los ictiosaurios no ponían huevos: daban a luz crías vivas dentro del agua, como hacen hoy los delfines! Se encontraron fósiles de madres con sus crías.", s: ["Los reptiles marinos respiraban aire y tenían que subir a la superficie, como las ballenas.", "Algunos mosasaurios superaban los 15 metros de largo.", "Las tortugas marinas son reptiles antiguos que nadaban en los mares de esa época y existen hasta hoy."], ex: { t: "Aleta vs. mano abierta", m: "una palangana con agua, una cuchara de madera o espátula ancha, un tenedor", p: ["Mueve el agua empujando con el tenedor, como si fuera una mano con los dedos separados.", "Ahora empuja con la cuchara ancha, como una aleta.", "¿Cuál empuja más agua? ¡Por eso los reptiles marinos tenían aletas anchas y no dedos sueltos!"] }, at: "Ficha del mar antiguo", m: "papel, lápices de colores azul y verde", p: ["Dibuja un mar antiguo con un ictiosaurio, un plesiosaurio y un mosasaurio.", "Agrega peces, amonites (conchas en espiral) y una tortuga.", "Escribe “Reptiles marinos: primos de los dinosaurios” y ponla en el museo."], q: "¿Cuál de estos monstruos del mar te daría más miedo encontrar?" } },

{ e: "🐤", art: { b: "🐤", s: ["🔍", "🪶", "🦖", "🐦"], c: ["#4E3A1B", "#C2904A"] },
pt: { h: "Nina achava que todo dinossauro era gigante. O vovô mostrou o desenho de um dinossauro do tamanho de um corvo, com penas e quatro asas. “Este é o Microraptor”, disse. “E o menor dinossauro de todos ainda está vivo: é o beija-flor!”", t: "Os pequenininhos", f: "Nem todo dinossauro era enorme. Muitos tinham o tamanho de galinhas, gatos ou cachorros. O Microraptor, que viveu na China, tinha penas nos braços e nas pernas, como se tivesse quatro asas, e provavelmente planava entre as árvores.", x: "O menor dinossauro que existe é o beija-flor-abelha, de Cuba, com cerca de 5 centímetros! Como as aves são dinossauros, ele ganha o título.", s: ["O Compsognathus, um dinossauro pequeno e rápido, tinha mais ou menos o tamanho de uma galinha.", "Os dinossauros pequenos são mais difíceis de achar, porque seus ossos frágeis se quebravam com facilidade antes de virar fósseis.", "Ser pequeno ajudava a se esconder, a subir em árvores e a gastar pouca comida."], ex: { t: "Do maior ao menor", m: "papel quadriculado, lápis, régua", p: ["Use cada quadradinho do papel como 1 metro.", "Desenhe em escala: um Argentinossauro com 35 quadradinhos, um T. rex com 12 e um Microraptor com menos de 1.", "Compare! O Microraptor quase some no papel. Que diferença de tamanhos!"] }, at: "Ficha dos mini dinos", m: "papel, lápis de cor", p: ["Desenhe um Microraptor com quatro asas de penas planando de uma árvore.", "Ao lado, desenhe um beija-flor com a frase: “O menor dinossauro vivo”.", "Coloque a ficha no museu, bem pequenininha, num cantinho!"], q: "Você prefere os dinossauros gigantes ou os pequenininhos? Por quê?" },
en: { h: "Nina thought every dinosaur was a giant. Grandpa showed her a drawing of a crow-sized dinosaur with feathers and four wings. “This is Microraptor,” he said. “And the smallest dinosaur of all is still alive: the hummingbird!”", t: "The little ones", f: "Not every dinosaur was enormous. Many were the size of chickens, cats or dogs. Microraptor, which lived in China, had feathers on its arms and legs, as if it had four wings, and probably glided between trees.", x: "The smallest dinosaur in existence is the bee hummingbird, from Cuba, at about 5 centimeters (2 inches)! Since birds are dinosaurs, it wins the title.", s: ["Compsognathus, a small, speedy dinosaur, was about the size of a chicken.", "Small dinosaurs are harder to find, because their fragile bones broke easily before they could become fossils.", "Being small helped them hide, climb trees and need less food."], ex: { t: "Biggest to smallest", m: "graph paper, pencil, ruler", p: ["Let each square on the paper stand for 1 meter.", "Draw to scale: an Argentinosaurus 35 squares long, a T. rex 12 squares and a Microraptor less than 1.", "Compare! Microraptor almost disappears on the page. What a difference in size!"] }, at: "Mini dino card", m: "paper, colored pencils", p: ["Draw a Microraptor with four feathered wings gliding from a tree.", "Next to it, draw a hummingbird with the words: “The smallest living dinosaur.”", "Put the card in the museum, very tiny, in a little corner!"], q: "Do you prefer the giant dinosaurs or the tiny ones? Why?" },
es: { h: "Nina creía que todos los dinosaurios eran gigantes. El abuelo le mostró el dibujo de un dinosaurio del tamaño de un cuervo, con plumas y cuatro alas. “Este es el Microraptor”, dijo. “¡Y el dinosaurio más pequeño de todos sigue vivo: es el colibrí!”", t: "Los chiquititos", f: "No todos los dinosaurios eran enormes. Muchos tenían el tamaño de gallinas, gatos o perros. El Microraptor, que vivió en China, tenía plumas en los brazos y en las patas, como si tuviera cuatro alas, y probablemente planeaba entre los árboles.", x: "¡El dinosaurio más pequeño que existe es el colibrí zunzuncito, de Cuba, de unos 5 centímetros! Como las aves son dinosaurios, se lleva el título.", s: ["El Compsognathus, un dinosaurio pequeño y rápido, tenía más o menos el tamaño de una gallina.", "Los dinosaurios pequeños son más difíciles de encontrar, porque sus huesos frágiles se rompían fácilmente antes de fosilizarse.", "Ser pequeño ayudaba a esconderse, trepar árboles y necesitar poca comida."], ex: { t: "Del más grande al más chico", m: "papel cuadriculado, lápiz, regla", p: ["Usa cada cuadradito del papel como 1 metro.", "Dibuja a escala: un Argentinosaurio de 35 cuadraditos, un T. rex de 12 y un Microraptor de menos de 1.", "¡Compara! El Microraptor casi desaparece en el papel. ¡Qué diferencia de tamaños!"] }, at: "Ficha de los mini dinos", m: "papel, lápices de colores", p: ["Dibuja un Microraptor con cuatro alas de plumas planeando desde un árbol.", "Al lado, dibuja un colibrí con la frase: “El dinosaurio vivo más pequeño”.", "¡Pon la ficha en el museo, bien chiquitita, en un rinconcito!"], q: "¿Prefieres los dinosaurios gigantes o los chiquititos? ¿Por qué?" } },

{ e: "👣", art: { b: "👣", s: ["🦶", "📏", "🏜️", "🦕"], c: ["#5A3A1B", "#B07A4A"] },
pt: { h: "Depois da chuva, Nina e Leo deixaram pegadas na lama do quintal. Quando a lama secou, as marcas ficaram lá, durinhas. “É assim que as pegadas de dinossauro viraram fósseis”, disse o vovô. “E na Paraíba existe um vale inteiro cheio delas!”", t: "Pegadas que contam histórias", f: "Quando um dinossauro pisava em lama mole, deixava uma pegada. Se a lama secasse e fosse coberta por camadas de areia, a marca podia virar pedra. As pegadas mostram como os dinossauros andavam, se andavam sozinhos ou em grupo e até se estavam correndo.", x: "O Vale dos Dinossauros, em Sousa, na Paraíba, tem milhares de pegadas fósseis de mais de 100 milhões de anos! É um dos lugares mais importantes do mundo para estudar pegadas.", s: ["Pelo espaço entre uma pegada e outra, os cientistas calculam a velocidade do dinossauro.", "Pegadas lado a lado de vários animais mostram que alguns dinossauros andavam em bandos.", "Uma pegada de saurópode pode ser tão grande que cabe uma criança sentada dentro."], ex: { t: "Detetive de pegadas", m: "uma bandeja com farinha, areia molhada ou lama, uma régua, papel e lápis", p: ["Ande devagar pela areia ou farinha e meça a distância entre um passo e outro.", "Agora corra e meça de novo.", "Os passos ficam mais longos quando você corre! Os cientistas usam essa mesma ideia nas pegadas de dinossauros."] }, at: "Ficha das pegadas", m: "papel, tinta guache ou lápis de cor", p: ["Desenhe uma trilha de pegadas de dinossauro: de três dedos (carnívoro) e redondas (saurópode).", "Invente uma história: quem passou por ali? Estava correndo ou passeando?", "Escreva a história na ficha e coloque no museu."], q: "Que história as suas pegadas contariam hoje?" },
en: { h: "After the rain, Nina and Leo left footprints in the backyard mud. When the mud dried, the prints stayed there, hard. “That's how dinosaur footprints became fossils,” Grandpa said. “And in Brazil there's a whole valley full of them!”", t: "Footprints that tell stories", f: "When a dinosaur stepped in soft mud, it left a footprint. If the mud dried and was covered by layers of sand, the print could turn to stone. Footprints show how dinosaurs walked, whether they traveled alone or in groups and even whether they were running.", x: "The Valley of the Dinosaurs, in Sousa, in the Brazilian state of Paraíba, has thousands of fossil footprints more than 100 million years old! It's one of the most important places in the world for studying tracks.", s: ["From the spacing between footprints, scientists calculate how fast the dinosaur was going.", "Side-by-side footprints from several animals show that some dinosaurs moved in herds.", "A sauropod footprint can be so big that a child could sit inside it."], ex: { t: "Footprint detective", m: "a tray with flour, wet sand or mud, a ruler, paper and pencil", p: ["Walk slowly across the sand or flour and measure the distance between steps.", "Now run and measure again.", "Your steps get longer when you run! Scientists use the same idea with dinosaur tracks."] }, at: "Footprint card", m: "paper, poster paint or colored pencils", p: ["Draw a trail of dinosaur footprints: three-toed (meat-eater) and round (sauropod).", "Invent a story: who passed by? Were they running or strolling?", "Write the story on the card and put it in the museum."], q: "What story would your footprints tell today?" },
es: { h: "Después de la lluvia, Nina y Leo dejaron huellas en el barro del patio. Cuando el barro se secó, las marcas quedaron ahí, duritas. “Así se convirtieron en fósiles las huellas de dinosaurio”, dijo el abuelo. “¡Y en Brasil hay un valle entero lleno de ellas!”", t: "Huellas que cuentan historias", f: "Cuando un dinosaurio pisaba barro blando, dejaba una huella. Si el barro se secaba y quedaba cubierto por capas de arena, la marca podía volverse piedra. Las huellas muestran cómo caminaban los dinosaurios, si andaban solos o en grupo y hasta si estaban corriendo.", x: "¡El Valle de los Dinosaurios, en Sousa, en el estado de Paraíba, Brasil, tiene miles de huellas fósiles de más de 100 millones de años! Es uno de los lugares más importantes del mundo para estudiar huellas.", s: ["Por el espacio entre una huella y otra, los científicos calculan la velocidad del dinosaurio.", "Huellas una al lado de la otra de varios animales muestran que algunos dinosaurios andaban en manadas.", "Una huella de saurópodo puede ser tan grande que entra un niño sentado adentro."], ex: { t: "Detective de huellas", m: "una bandeja con harina, arena mojada o barro, una regla, papel y lápiz", p: ["Camina despacio por la arena o la harina y mide la distancia entre un paso y otro.", "Ahora corre y mide otra vez.", "¡Los pasos son más largos cuando corres! Los científicos usan la misma idea con las huellas de dinosaurios."] }, at: "Ficha de las huellas", m: "papel, témpera o lápices de colores", p: ["Dibuja un camino de huellas de dinosaurio: de tres dedos (carnívoro) y redondas (saurópodo).", "Inventa una historia: ¿quién pasó por ahí? ¿Iba corriendo o paseando?", "Escribe la historia en la ficha y ponla en el museo."], q: "¿Qué historia contarían tus huellas hoy?" } },

{ e: "🏃", art: { b: "🏃", s: ["🦖", "💨", "⏱️", "🐓"], c: ["#4E1B1B", "#C24A3A"] },
pt: { h: "Leo perguntou se ele conseguiria fugir de um T. rex correndo. O vovô coçou a cabeça e riu: “Os cientistas acham que o T. rex não era tão rápido quanto nos filmes, porque era pesado demais. Mas eu não arriscaria!” Nina pegou o cronômetro para uma corrida no quintal.", t: "Quão rápidos eram os dinossauros?", f: "Para calcular a velocidade de um dinossauro, os cientistas medem o tamanho das pernas, os ossos e a distância entre as pegadas. Dinossauros leves e de pernas compridas, parecidos com avestruzes, eram os mais rápidos. Os gigantes pesados andavam mais devagar.", x: "Alguns dinossauros parecidos com avestruzes, como o Galimimo, podiam correr talvez mais de 50 quilômetros por hora, tão rápido quanto um carro na cidade!", s: ["Os cientistas calculam que um T. rex adulto corria mais ou menos como uma pessoa correndo rápido, não como um carro.", "Os saurópodes gigantes andavam devagar, como elefantes.", "A avestruz, que é um dinossauro vivo, corre até uns 70 quilômetros por hora."], ex: { t: "Corrida de dinossauros", m: "um espaço aberto, um cronômetro, uma fita métrica ou passos, giz ou cordas para marcar", p: ["Marque uma pista de uns 20 passos.", "Faça três corridas: andando como um saurópode pesado, correndo normal e correndo como um raptor leve.", "Cronometre cada uma e anote. Qual “dinossauro” foi o mais rápido?"] }, at: "Ficha do pódio", m: "papel, lápis de cor", p: ["Desenhe um pódio com três lugares.", "Coloque no 1º lugar o dinossauro mais rápido, no 2º um médio e no 3º um gigante lento.", "Coloque a ficha no museu com uma medalha desenhada."], q: "Qual animal de hoje você acha que ganharia uma corrida contra um T. rex?" },
en: { h: "Leo asked whether he could outrun a T. rex. Grandpa scratched his head and laughed: “Scientists think T. rex wasn't as fast as in the movies, because it was so heavy. But I wouldn't risk it!” Nina grabbed the stopwatch for a backyard race.", t: "How fast were dinosaurs?", f: "To figure out a dinosaur's speed, scientists measure its leg length, its bones and the distance between footprints. Light, long-legged dinosaurs that looked like ostriches were the fastest. Heavy giants moved more slowly.", x: "Some ostrich-like dinosaurs, like Gallimimus, may have been able to run more than 50 kilometers per hour (30 mph), as fast as a car in town!", s: ["Scientists estimate that an adult T. rex ran about as fast as a person sprinting, not like a car.", "Giant sauropods walked slowly, like elephants.", "The ostrich, a living dinosaur, can run up to about 70 kilometers per hour (43 mph)."], ex: { t: "Dinosaur race", m: "an open space, a stopwatch, a tape measure or steps, chalk or rope to mark lines", p: ["Mark out a track about 20 steps long.", "Do three races: walking like a heavy sauropod, running normally and running like a light raptor.", "Time each one and write it down. Which “dinosaur” was fastest?"] }, at: "Podium card", m: "paper, colored pencils", p: ["Draw a podium with three places.", "Put the fastest dinosaur in 1st place, a medium one in 2nd and a slow giant in 3rd.", "Put the card in the museum with a medal drawn on it."], q: "Which animal today do you think would win a race against a T. rex?" },
es: { h: "Leo preguntó si podría escaparse corriendo de un T. rex. El abuelo se rascó la cabeza y se rió: “Los científicos creen que el T. rex no era tan rápido como en las películas, porque era demasiado pesado. ¡Pero yo no me arriesgaría!” Nina agarró el cronómetro para una carrera en el patio.", t: "¿Qué tan rápidos eran los dinosaurios?", f: "Para calcular la velocidad de un dinosaurio, los científicos miden el largo de las patas, los huesos y la distancia entre las huellas. Los dinosaurios livianos y de patas largas, parecidos a avestruces, eran los más rápidos. Los gigantes pesados caminaban más despacio.", x: "¡Algunos dinosaurios parecidos a avestruces, como el Gallimimus, quizás podían correr a más de 50 kilómetros por hora, tan rápido como un auto en la ciudad!", s: ["Los científicos calculan que un T. rex adulto corría más o menos como una persona corriendo rápido, no como un auto.", "Los saurópodos gigantes caminaban despacio, como elefantes.", "El avestruz, que es un dinosaurio vivo, corre hasta unos 70 kilómetros por hora."], ex: { t: "Carrera de dinosaurios", m: "un espacio abierto, un cronómetro, una cinta métrica o pasos, tiza o sogas para marcar", p: ["Marca una pista de unos 20 pasos.", "Haz tres carreras: caminando como un saurópodo pesado, corriendo normal y corriendo como un raptor liviano.", "Cronometra cada una y anótala. ¿Qué “dinosaurio” fue el más rápido?"] }, at: "Ficha del podio", m: "papel, lápices de colores", p: ["Dibuja un podio con tres lugares.", "Pon en el 1.º lugar al dinosaurio más rápido, en el 2.º a uno mediano y en el 3.º a un gigante lento.", "Pon la ficha en el museo con una medalla dibujada."], q: "¿Qué animal de hoy crees que le ganaría una carrera a un T. rex?" } },

{ e: "🎺", art: { b: "🎺", s: ["🎨", "🦕", "🔊", "🪶"], c: ["#3A1B4E", "#8A4AB0"] },
pt: { h: "Nina pintou seu dinossauro de roxo com bolinhas amarelas. Leo disse que estava errado, que dinossauro era verde. “Por muito tempo ninguém sabia”, disse o vovô. “Mas hoje os cientistas conseguem descobrir a cor de alguns! E também têm pistas de como alguns soavam.”", t: "Cores e sons dos dinossauros", f: "Dentro de algumas penas fossilizadas, os cientistas encontraram estruturas microscópicas que guardavam a cor. Assim descobriram que um pequeno dinossauro chamado Sinossauroptérix era castanho-avermelhado com a cauda listrada! Quanto aos sons, os cientistas estudam os ossos da cabeça e da garganta para imaginar como eles eram.", x: "O Parassaurolofo tinha uma crista oca e comprida na cabeça. Quando o ar passava por dentro dela, provavelmente fazia um som grave, como um trombone!", s: ["O Anquiórnis, um dinossauro pequeno com penas, era preto e branco, com uma crista avermelhada.", "Muitos cientistas acham que alguns dinossauros “falavam” com sons de boca fechada, parecidos com os arrulhos dos pombos e os roncos dos crocodilos.", "As cores serviam para se camuflar, atrair parceiros ou avisar outros animais."], ex: { t: "Crista que soa", m: "tubos de papelão de tamanhos diferentes (rolo de papel higiênico, de papel-toalha, de papel-alumínio)", p: ["Encoste a boca numa ponta de cada tubo e faça um som de “buuuu” lá dentro.", "Compare: o tubo mais comprido faz um som mais grave.", "Imagine o som da crista do Parassaurolofo, com mais de 1 metro de tubo! Inventem juntos o “chamado do dinossauro”."] }, at: "Ficha das cores", m: "papel, lápis de cor ou tinta", p: ["Desenhe o Sinossauroptérix castanho com a cauda listrada, como os cientistas descobriram.", "Ao lado, desenhe um dinossauro inventado com as cores que você quiser e explique para que servem.", "Coloque as duas fichas no museu."], q: "Que cor você daria para o seu dinossauro favorito? E que som ele faria?" },
en: { h: "Nina painted her dinosaur purple with yellow polka dots. Leo said it was wrong, that dinosaurs were green. “For a long time nobody knew,” said Grandpa. “But today scientists can figure out the color of some! And they have clues about how some sounded too.”", t: "Dinosaur colors and sounds", f: "Inside some fossilized feathers, scientists found microscopic structures that held color. That's how they discovered that a small dinosaur called Sinosauropteryx was reddish-brown with a striped tail! As for sounds, scientists study head and throat bones to imagine what they were like.", x: "Parasaurolophus had a long, hollow crest on its head. When air passed through it, it probably made a deep sound, like a trombone!", s: ["Anchiornis, a small feathered dinosaur, was black and white with a reddish crest.", "Many scientists think some dinosaurs “talked” with closed-mouth sounds, like pigeons' coos and crocodiles' rumbles.", "Colors helped them camouflage, attract mates or warn other animals."], ex: { t: "Sounding crest", m: "cardboard tubes of different lengths (toilet paper, paper towel and foil rolls)", p: ["Put your mouth to one end of each tube and make a “booo” sound into it.", "Compare: the longer tube makes a deeper sound.", "Imagine the sound of Parasaurolophus's crest, with more than a meter of tube! Make up a “dinosaur call” together."] }, at: "Colors card", m: "paper, colored pencils or paint", p: ["Draw Sinosauropteryx in reddish-brown with a striped tail, as scientists discovered.", "Next to it, draw an invented dinosaur in any colors you like and explain what they're for.", "Put both cards in the museum."], q: "What color would you give your favorite dinosaur? And what sound would it make?" },
es: { h: "Nina pintó su dinosaurio de violeta con lunares amarillos. Leo dijo que estaba mal, que los dinosaurios eran verdes. “Durante mucho tiempo nadie lo sabía”, dijo el abuelo. “¡Pero hoy los científicos pueden descubrir el color de algunos! Y también tienen pistas de cómo sonaban algunos.”", t: "Colores y sonidos de los dinosaurios", f: "Dentro de algunas plumas fosilizadas, los científicos encontraron estructuras microscópicas que guardaban el color. ¡Así descubrieron que un pequeño dinosaurio llamado Sinosauropteryx era castaño rojizo con la cola rayada! En cuanto a los sonidos, estudian los huesos de la cabeza y la garganta para imaginar cómo eran.", x: "¡El Parasaurolophus tenía una cresta hueca y larga en la cabeza! Cuando el aire pasaba por adentro, probablemente hacía un sonido grave, como un trombón.", s: ["El Anchiornis, un pequeño dinosaurio con plumas, era blanco y negro, con una cresta rojiza.", "Muchos científicos creen que algunos dinosaurios “hablaban” con sonidos de boca cerrada, parecidos al arrullo de las palomas y los ronquidos de los cocodrilos.", "Los colores servían para camuflarse, atraer pareja o avisar a otros animales."], ex: { t: "Cresta que suena", m: "tubos de cartón de distintos tamaños (rollo de papel higiénico, de cocina y de aluminio)", p: ["Apoya la boca en una punta de cada tubo y haz un sonido de “buuu” adentro.", "Compara: el tubo más largo hace un sonido más grave.", "¡Imagina el sonido de la cresta del Parasaurolophus, con más de 1 metro de tubo! Inventen juntos el “llamado del dinosaurio”."] }, at: "Ficha de los colores", m: "papel, lápices de colores o pintura", p: ["Dibuja el Sinosauropteryx castaño con la cola rayada, como descubrieron los científicos.", "Al lado, dibuja un dinosaurio inventado con los colores que quieras y explica para qué sirven.", "Pon las dos fichas en el museo."], q: "¿Qué color le darías a tu dinosaurio favorito? ¿Y qué sonido haría?" } },

{ e: "🦴", art: { b: "🦴", s: ["🦖", "⛏️", "🏛️", "⭐"], c: ["#0B4F2C", "#D4B02C"] },
pt: { h: "O vovô contou que um dinossauro brasileiro ganhou o nome de Irritator, porque deixou os cientistas irritadíssimos. “Alguém tinha colado pedaços de gesso no crânio para ele parecer maior e ser vendido mais caro”, explicou. Leo achou o nome a coisa mais engraçada do mundo.", t: "Dinossauros do Brasil", f: "O Brasil tem dezenas de espécies de dinossauros descobertas, de vários estados. Há o Oxalaia, um caçador de peixes do Maranhão; o Maxakalisaurus, um saurópode de Minas Gerais; e o Irritator, do Ceará. Muitos foram encontrados por pesquisadores brasileiros.", x: "O Ubirajara, um pequeno dinossauro com penas do Ceará, foi levado para fora do país de forma irregular. Depois de uma grande campanha de cientistas brasileiros, ele voltou para casa em 2023!", s: ["A lei brasileira diz que os fósseis pertencem ao país e não podem ser vendidos.", "Os nomes dos dinossauros brasileiros muitas vezes homenageiam povos indígenas e lugares, como o Maxakalisaurus, que lembra o povo Maxakali.", "Museus no Brasil, como o Museu Nacional, no Rio de Janeiro, guardam fósseis importantes."], ex: { t: "Remontando o crânio", m: "um desenho de crânio de dinossauro em papel, tesoura, fita adesiva, papel de outra cor", p: ["Desenhe um crânio de dinossauro e recorte em 6 pedaços, como se tivesse quebrado.", "Peça para alguém montar o quebra-cabeça. Depois, troque um pedaço por um de outra cor, de “gesso”.", "A pessoa percebe a peça falsa? Os cientistas precisam ser detetives para descobrir o que é fóssil de verdade!"] }, at: "Ficha do Brasil jurássico", m: "um mapa do Brasil, lápis de cor", p: ["Marque no mapa os estados onde foram encontrados dinossauros: Rio Grande do Sul, Minas Gerais, Maranhão, Ceará, Paraíba e São Paulo.", "Desenhe um dinossauro pequeno em cada um.", "Coloque o mapa no museu com o título “Dinossauros brasileiros”."], q: "Por que você acha que os fósseis devem ficar no país onde foram encontrados?" },
en: { h: "Grandpa told them that a Brazilian dinosaur was named Irritator because it irritated scientists so much. “Someone had glued plaster onto the skull to make it look bigger and sell it for more money,” he explained. Leo thought the name was the funniest thing in the world.", t: "Dinosaurs of Brazil", f: "Brazil has dozens of known dinosaur species from many states. There's Oxalaia, a fish-eating hunter from Maranhão; Maxakalisaurus, a sauropod from Minas Gerais; and Irritator, from Ceará. Many were found by Brazilian researchers.", x: "Ubirajara, a small feathered dinosaur from Ceará, was taken out of Brazil improperly. After a big campaign by Brazilian scientists, it came back home in 2023!", s: ["Brazilian law says fossils belong to the country and cannot be sold.", "Brazilian dinosaur names often honor Indigenous peoples and places, like Maxakalisaurus, named after the Maxakali people.", "Museums in Brazil, like the National Museum in Rio de Janeiro, hold important fossils."], ex: { t: "Rebuilding the skull", m: "a drawing of a dinosaur skull on paper, scissors, tape, paper of another color", p: ["Draw a dinosaur skull and cut it into 6 pieces, as if it had broken.", "Ask someone to put the puzzle together. Then swap one piece for one of another color, the “plaster.”", "Does the person spot the fake piece? Scientists have to be detectives to tell what's real fossil!"] }, at: "Brazil fossil map card", m: "a map of Brazil, colored pencils", p: ["Mark the states where dinosaurs have been found: Rio Grande do Sul, Minas Gerais, Maranhão, Ceará, Paraíba and São Paulo.", "Draw a small dinosaur in each one.", "Put the map in the museum with the title “Brazilian dinosaurs.”"], q: "Why do you think fossils should stay in the country where they were found?" },
es: { h: "El abuelo contó que un dinosaurio brasileño recibió el nombre de Irritator porque irritó muchísimo a los científicos. “Alguien le había pegado pedazos de yeso al cráneo para que pareciera más grande y venderlo más caro”, explicó. A Leo el nombre le pareció lo más gracioso del mundo.", t: "Dinosaurios de Brasil", f: "Brasil tiene decenas de especies de dinosaurios descubiertas, de varios estados. Está el Oxalaia, un cazador de peces de Maranhão; el Maxakalisaurus, un saurópodo de Minas Gerais; y el Irritator, de Ceará. Muchos fueron encontrados por investigadores brasileños.", x: "¡El Ubirajara, un pequeño dinosaurio con plumas de Ceará, fue sacado del país de forma irregular. Después de una gran campaña de científicos brasileños, volvió a casa en 2023!", s: ["La ley brasileña dice que los fósiles pertenecen al país y no se pueden vender.", "Los nombres de los dinosaurios brasileños muchas veces homenajean a pueblos indígenas y lugares, como el Maxakalisaurus, que recuerda al pueblo maxakali.", "Museos de Brasil, como el Museo Nacional de Río de Janeiro, guardan fósiles importantes."], ex: { t: "Rearmando el cráneo", m: "un dibujo de cráneo de dinosaurio en papel, tijera, cinta adhesiva, papel de otro color", p: ["Dibuja un cráneo de dinosaurio y recórtalo en 6 pedazos, como si se hubiera roto.", "Pide a alguien que arme el rompecabezas. Después cambia un pedazo por uno de otro color, de “yeso”.", "¿La persona descubre la pieza falsa? ¡Los científicos tienen que ser detectives para saber qué es fósil de verdad!"] }, at: "Ficha del mapa de fósiles", m: "un mapa de Sudamérica, lápices de colores", p: ["Marca en el mapa lugares donde se encontraron dinosaurios: el sur y el nordeste de Brasil y la Patagonia argentina.", "Dibuja un dinosaurio pequeño en cada uno.", "Pon el mapa en el museo con el título “Dinosaurios de Sudamérica”."], q: "¿Por qué crees que los fósiles deben quedarse en el país donde se encontraron?" } },

{ e: "🏛️", art: { b: "🏛️", s: ["🦴", "🦖", "🔦", "🖼️"], c: ["#3A3A3A", "#8A8A7A"] },
pt: { h: "O vovô levou Nina e Leo a um museu de verdade. No salão principal, um esqueleto gigante parecia que ia andar a qualquer momento. “É tudo osso de verdade?”, sussurrou Leo. “Algumas partes, sim. Outras são cópias perfeitas”, explicou o vovô. “Os ossos originais são preciosos demais.”", t: "Esqueletos e museus", f: "Montar um esqueleto de dinossauro leva meses ou anos. Como os ossos fósseis são muito pesados e frágeis, muitos museus mostram réplicas, cópias feitas com moldes, e guardam os originais em lugares seguros para os cientistas estudarem.", x: "Em 2018, um incêndio atingiu o Museu Nacional, no Rio de Janeiro, o museu mais antigo do Brasil. Muita coisa se perdeu, mas pesquisadores trabalharam muito para recuperar peças e reconstruir o museu!", s: ["Quase nunca se encontra um esqueleto completo: os cientistas completam as partes que faltam comparando com parentes.", "Os ossos são presos em estruturas de metal escondidas para ficarem em pé.", "Visitar museus ajuda a ver de perto como a ciência descobre o passado."], ex: { t: "Esqueleto de cotonete", m: "papel preto, cotonetes, cola branca, tesoura (com um adulto)", p: ["Desenhe a silhueta de um dinossauro no papel preto com giz ou lápis claro.", "Corte cotonetes em tamanhos diferentes (com um adulto) para fazer a coluna, as costelas, as pernas e a cauda.", "Cole tudo no lugar: parece um esqueleto de museu brilhando no escuro!"] }, at: "Ficha do curador", m: "papel, lápis de cor", p: ["Imagine que você é o curador, a pessoa que organiza o museu.", "Desenhe um mapa do seu Museu dos Dinossauros com as salas e onde fica cada ficha.", "Escreva as regras do museu, como “não tocar nos fósseis”."], q: "Se você pudesse visitar qualquer museu do mundo, qual seria?" },
en: { h: "Grandpa took Nina and Leo to a real museum. In the main hall, a giant skeleton looked like it might start walking at any moment. “Is it all real bone?” Leo whispered. “Some parts, yes. Others are perfect copies,” Grandpa explained. “The original bones are too precious.”", t: "Skeletons and museums", f: "Mounting a dinosaur skeleton takes months or years. Because fossil bones are very heavy and fragile, many museums display replicas, copies made from molds, and keep the originals safe for scientists to study.", x: "In 2018, a fire struck the National Museum in Rio de Janeiro, Brazil's oldest museum. Much was lost, but researchers worked very hard to recover pieces and rebuild the museum!", s: ["A complete skeleton is almost never found: scientists fill in missing parts by comparing with relatives.", "The bones are attached to hidden metal frames so they can stand up.", "Visiting museums helps you see up close how science discovers the past."], ex: { t: "Cotton swab skeleton", m: "black paper, cotton swabs, white glue, scissors (with a grown-up)", p: ["Draw a dinosaur silhouette on the black paper with chalk or a light pencil.", "Cut cotton swabs into different lengths (with a grown-up) for the spine, ribs, legs and tail.", "Glue everything in place: it looks like a museum skeleton glowing in the dark!"] }, at: "Curator card", m: "paper, colored pencils", p: ["Imagine you're the curator, the person who organizes the museum.", "Draw a map of your Dinosaur Museum with its rooms and where each card goes.", "Write the museum rules, like “do not touch the fossils.”"], q: "If you could visit any museum in the world, which would it be?" },
es: { h: "El abuelo llevó a Nina y Leo a un museo de verdad. En el salón principal, un esqueleto gigante parecía que iba a caminar en cualquier momento. “¿Es todo hueso de verdad?”, susurró Leo. “Algunas partes sí. Otras son copias perfectas”, explicó el abuelo. “Los huesos originales son demasiado valiosos.”", t: "Esqueletos y museos", f: "Armar un esqueleto de dinosaurio lleva meses o años. Como los huesos fósiles son muy pesados y frágiles, muchos museos muestran réplicas, copias hechas con moldes, y guardan los originales en lugares seguros para que los estudien los científicos.", x: "¡En 2018, un incendio afectó al Museo Nacional de Río de Janeiro, el museo más antiguo de Brasil. Se perdió mucho, pero los investigadores trabajaron muchísimo para recuperar piezas y reconstruir el museo!", s: ["Casi nunca se encuentra un esqueleto completo: los científicos completan las partes que faltan comparando con parientes.", "Los huesos se sujetan a estructuras de metal escondidas para quedar de pie.", "Visitar museos ayuda a ver de cerca cómo la ciencia descubre el pasado."], ex: { t: "Esqueleto de hisopos", m: "papel negro, hisopos de algodón, cola vinílica, tijera (con un adulto)", p: ["Dibuja la silueta de un dinosaurio en el papel negro con tiza o lápiz claro.", "Corta hisopos de distintos tamaños (con un adulto) para hacer la columna, las costillas, las patas y la cola.", "Pega todo en su lugar: ¡parece un esqueleto de museo brillando en la oscuridad!"] }, at: "Ficha del curador", m: "papel, lápices de colores", p: ["Imagina que eres el curador, la persona que organiza el museo.", "Dibuja un mapa de tu Museo de los Dinosaurios con las salas y dónde va cada ficha.", "Escribe las reglas del museo, como “no tocar los fósiles”."], q: "Si pudieras visitar cualquier museo del mundo, ¿cuál sería?" } },
];
